// Copies a CV HTML generated by career-ops into this site, adding the web-only bits:
// the language switcher, the "download PDF" link, noindex and hreflang tags.
// Usage: node tools/publish-cv.mjs <lang: pt|en|es> <path/to/generated-cv.html>
import { readFile, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const SITE = "https://cv.dasilva-thiago.dev";
const LANGS = {
  pt: { label: "Português", download: "Baixar PDF", title: "Thiago da Silva | Currículo", hreflang: "pt-BR" },
  en: { label: "English", download: "Download PDF", title: "Thiago da Silva | Resume", hreflang: "en" },
  es: { label: "Español", download: "Descargar PDF", title: "Thiago da Silva | Currículum", hreflang: "es" },
};

const [lang, source] = process.argv.slice(2);
if (!LANGS[lang] || !source) {
  console.error("usage: node tools/publish-cv.mjs <pt|en|es> <generated-cv.html>");
  process.exit(1);
}

const siteDir = join(dirname(fileURLToPath(import.meta.url)), "..");
const pdf = `/thiago-da-silva-cv-${lang}.pdf`;
let html = await readFile(source, "utf8");

const head = [
  '<meta name="robots" content="noindex">',
  `<link rel="canonical" href="${SITE}/${lang}">`,
  ...Object.entries(LANGS).map(([code, l]) => `<link rel="alternate" hreflang="${l.hreflang}" href="${SITE}/${code}">`),
  `<style>
  .cv-webbar { max-width: 210mm; margin: 0 auto; padding: 12px 16px 0; display: flex; flex-wrap: wrap; gap: 8px 16px;
    justify-content: space-between; align-items: center; font: 14px/1.4 Arial, sans-serif; }
  .cv-webbar nav { display: flex; gap: 12px; }
  .cv-webbar a { color: hsl(187 74% 28%); }
  .cv-webbar a[aria-current="page"] { font-weight: 700; text-decoration: none; color: #222; }
  .cv-webbar .cv-download { padding: 6px 14px; border: 1.5px solid hsl(187 74% 32%); border-radius: 6px; text-decoration: none; font-weight: 600; }
  @media screen { html body .page { padding: 16px 16px 32px; } }
  @media print { .cv-webbar { display: none; } }
</style>`,
].join("\n");

const nav = Object.entries(LANGS)
  .map(([code, l]) =>
    code === lang ? `<a href="/${code}" aria-current="page">${l.label}</a>` : `<a href="/${code}" hreflang="${l.hreflang}">${l.label}</a>`,
  )
  .join("");
const bar = `<div class="cv-webbar"><nav aria-label="Language">${nav}</nav><a class="cv-download" href="${pdf}" download>${LANGS[lang].download}</a></div>`;

html = html.replace(/<title>[^<]*<\/title>/, `<title>${LANGS[lang].title}</title>\n${head}`);
html = html.replace(/<body([^>]*)>/, `<body$1>\n${bar}`);
if (!html.includes("cv-webbar")) {
  console.error("could not inject the web bar: <title> or <body> not found");
  process.exit(1);
}

await writeFile(join(siteDir, `${lang}.html`), html);
console.log(`wrote ${lang}.html`);
